import{_ as r}from"./chunks/benchmark.JDxUlm17.js";import{_ as o,o as a,c as e,ai as n}from"./chunks/framework.C33Uq6m-.js";const b=JSON.parse('{"title":"基准测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/benchmark.md","filePath":"zh/guide/benchmark.md"}'),l={name:"zh/guide/benchmark.md"};function s(i,t,d,h,g,c){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="基准测试" tabindex="-1">基准测试 <a class="header-anchor" href="#基准测试" aria-label="Permalink to &quot;基准测试&quot;">​</a></h1><p>基准测试页使用真实的 token logprobs 对你的本地模型进行标准化评测，给出客观的性能数据。</p><p><strong>侧边栏位置：</strong> 基准测试 <strong>路由：</strong> <code>/benchmark</code></p><p><img src="'+r+'" alt="基准测试界面"></p><h2 id="什么是「精准基准测试」" tabindex="-1">什么是「精准基准测试」？ <a class="header-anchor" href="#什么是「精准基准测试」" aria-label="Permalink to &quot;什么是「精准基准测试」？&quot;">​</a></h2><p>普通的基准测试只检查答案对不对，而 LLMxRay 的精准基准测试会通过 Ollama 的 OpenAI 兼容接口（<code>/v1/chat/completions</code>）捕获<strong>真实的 token logprobs</strong>。这样你拿到的不只是准确率，而是每个答案背后真实的置信度数据。</p><h2 id="内置测试集" tabindex="-1">内置测试集 <a class="header-anchor" href="#内置测试集" aria-label="Permalink to &quot;内置测试集&quot;">​</a></h2><table tabindex="0"><thead><tr><th>测试集</th><th>题目类型</th><th>考察什么</th></tr></thead><tbody><tr><td><strong>ARC</strong></td><td>科学推理</td><td>中小学科学题</td></tr><tr><td><strong>GSM8K</strong></td><td>数学应用题</td><td>多步算术推理</td></tr><tr><td><strong>HellaSwag</strong></td><td>句子补全</td><td>常识推理</td></tr><tr><td><strong>MMLU-Pro</strong></td><td>多学科</td><td>跨领域的广泛学术知识</td></tr><tr><td><strong>TruthfulQA</strong></td><td>真实性</td><td>对常见误解的抵抗力</td></tr></tbody></table><h2 id="运行一次基准测试" tabindex="-1">运行一次基准测试 <a class="header-anchor" href="#运行一次基准测试" aria-label="Permalink to &quot;运行一次基准测试&quot;">​</a></h2><ol><li>从下拉框选择一个<strong>模型</strong>。</li><li>勾选一个或多个<strong>测试集</strong>。</li><li>点击<strong>运行</strong>。结果会实时流式呈现。</li></ol><p>运行过程中你可以看到：</p><ul><li><strong>实时进度</strong> —— 已答题数、当前准确率</li><li><strong>逐题结果</strong> —— 正确 / 错误、模型的答案、置信度分数</li><li><strong>延迟数据</strong> —— 每题的 TTFT 与 token/秒</li></ul><h2 id="推理模型" tabindex="-1">推理模型 <a class="header-anchor" href="#推理模型" aria-label="Permalink to &quot;推理模型&quot;">​</a></h2><p>对于 DeepSeek-R1 这类推理模型，基准测试会使用<strong>动态 token 预算</strong> —— 允许模型为 <code>&lt;think&gt;</code> 块使用更多 token，且不计入答案部分。这样推理模型不会因为「把思考过程写出来」而被扣分。</p><h2 id="结果可视化" tabindex="-1">结果可视化 <a class="header-anchor" href="#结果可视化" aria-label="Permalink to &quot;结果可视化&quot;">​</a></h2><p>完成后，结果以如下形式呈现：</p><ul><li><strong>准确率分数</strong> —— 总体正确百分比</li><li><strong>分类别细分</strong> —— 各测试集内按学科划分的准确率</li><li><strong>雷达图</strong> —— 跨类别的可视化对比</li><li><strong>置信度分布</strong> —— 基于 logprob 的置信度分数直方图</li></ul><h2 id="对比结果" tabindex="-1">对比结果 <a class="header-anchor" href="#对比结果" aria-label="Permalink to &quot;对比结果&quot;">​</a></h2><p>在多个模型上运行同一个测试集，可以比较：</p><ul><li>哪个模型在哪些学科上更准确</li><li>置信度校准 —— 高置信度是否真的对应正确答案？</li><li>速度与准确率之间的取舍</li></ul><p>结果存储在 IndexedDB 中，因此可以跨会话对比。</p><h2 id="自定义测试集" tabindex="-1">自定义测试集 <a class="header-anchor" href="#自定义测试集" aria-label="Permalink to &quot;自定义测试集&quot;">​</a></h2><p>点击<strong>导入</strong>可加载自定义测试集。期望的格式是一个 JSON 文件，包含：</p><ul><li>测试集名称与描述</li><li>题目数组，每题包含：题干、选项、正确答案索引，以及可选的类别</li></ul><p>你也可以直接在应用内用<strong>测试集构建器</strong>创建自定义测试集 —— 手动添加题目，或让本地模型替你生成。详见<a href="./benchmark-builder.html">测试集构建器指南</a>。</p><h2 id="导出结果" tabindex="-1">导出结果 <a class="header-anchor" href="#导出结果" aria-label="Permalink to &quot;导出结果&quot;">​</a></h2><p>点击结果标题栏中的<strong>导出</strong>按钮，可以把基准测试数据下载为 <strong>JSON</strong>、<strong>CSV</strong> 或 <strong>Markdown</strong>。JSON 包含完整的结构化数据，便于脚本处理与分析；CSV 是扁平的表格数据，适合电子表格；Markdown 则是可直接粘贴进文档的格式化报告。关于全部导出选项以及分享到 GitHub Discussions，详见<a href="./export.html">导出指南</a>。</p><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>logprobs 需要 <code>/v1</code> 接口</strong> —— 这里用的是 Ollama 的 OpenAI 兼容 API，而不是原生的 <code>/api</code> 接口。</li><li><strong>先跑小测试集</strong> —— 先用一个子集估算完整运行需要多久。</li><li><strong>支持续跑</strong> —— 如果测试中断，可以从中断处继续。</li><li><strong>对比量化等级</strong> —— 用 Q4 和 Q8 跑同一个模型，看看量化对准确率的影响。</li></ul>',29)])])}const m=o(l,[["render",s]]);export{b as __pageData,m as default};
